{
  "done": false,
  "tool": "manage_backends",
  "args": {
    "name": "Healthcare Research Data",
    "url": "http://localhost:7808",
    "operation": "add",
    "widgets_json": {
      "catalyst_calendar_table": {
        "name": "Catalyst Calendar Table",
        "description": "Healthcare catalysts and impact scores.",
        "endpoint": "/catalyst-calendar-table",
        "type": "table",
        "gridData": {
          "w": 20,
          "h": 9
        },
        "params": [
          {
            "paramName": "ticker",
            "type": "text",
            "label": "Ticker",
            "value": "MRNA",
            "description": "Catalyst Calendar Table focus field."
          }
        ]
      },
      "catalyst_metric": {
        "name": "Catalysts 30d",
        "description": "Catalysts in the next 30 days.",
        "endpoint": "/catalyst-count",
        "type": "metric",
        "gridData": {
          "w": 6,
          "h": 4
        }
      }
    },
    "apps_json": [
      {
        "name": "Catalyst Calendar",
        "description": "Catalyst calendar and 30-day count.",
        "tabs": {
          "calendar": {
            "id": "calendar",
            "name": "Calendar",
            "layout": [
              {
                "i": "catalyst_calendar_table",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          },
          "count": {
            "id": "count",
            "name": "Count",
            "layout": [
              {
                "i": "catalyst_metric",
                "x": 0,
                "y": 0,
                "w": 20,
                "h": 9
              }
            ]
          }
        }
      }
    ]
  }
}

{
  "done": false,
  "tool": "add_generative_widget",
  "args": {
    "dashboard_id": "dash_002",
    "data": "Catalyst Calendar is live from Healthcare Research Data: catalyst calendar ready.",
